{
  "name": "opencode-claude-memory",
  "version": "2.3.0",
  "type": "module",
  "description": "OpenCode plugin for Claude Code memory: persistent, local-first shared memory with Claude Code-compatible Markdown files, LLM recall, in-process auto extraction, and auto-dream consolidation",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "engines": {
    "opencode": ">=1.18.29"
  },
  "scripts": {
    "build": "tsc -p tsconfig.build.json",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "lint": "biome ci .",
    "format": "biome check --write .",
    "test": "bun test",
    "evals": "bun run test/evals/run.ts",
    "prepack": "npm run build"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/kuitos/opencode-claude-memory.git"
  },
  "bugs": {
    "url": "https://github.com/kuitos/opencode-claude-memory/issues"
  },
  "homepage": "https://github.com/kuitos/opencode-claude-memory#readme",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-ai",
    "claude",
    "claude-code",
    "claude-code-memory",
    "claude-memory",
    "plugin",
    "memory",
    "persistent-memory",
    "agent-memory",
    "ai-memory",
    "cross-session-memory",
    "shared-memory",
    "local-first",
    "markdown-memory",
    "coding-agent",
    "developer-tools",
    "claude-code-compatible"
  ],
  "license": "MIT",
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.18.29",
    "@opencode/plugin": ">=2.0.0"
  },
  "peerDependenciesMeta": {
    "@opencode-ai/plugin": {
      "optional": true
    },
    "@opencode/plugin": {
      "optional": true
    }
  },
  "dependencies": {
    "zod": "^3.25.0"
  },
  "devDependencies": {
    "@biomejs/biome": "^2",
    "@opencode-ai/plugin": "^1.18.16",
    "@opencode/client": "2.0.22",
    "@opencode/plugin": "2.0.22",
    "@opencode/schema": "2.0.22",
    "bun-types": "^1.3.11",
    "conventional-changelog-conventionalcommits": "^9",
    "typescript": "^6.0.2"
  }
}
